actor DailyGoal {
    private var completed = 0
    private var generation = 0
    func reset() { generation += 1; completed = 0 }
    func read() -> Int { completed }
    func addAfterCheck(check: () async -> Bool) async -> Bool {
        let expected = generation
        guard await check() else { return false }
        guard generation == expected else { return false }
        completed += 1
        return true
    }
}

Сброс во время check приводит к false и итоговому 0, без сброса — true и 1.
